    /// <summary>
    /// Process a payment charge. Reads amount/currency/source/metadata from
    /// <paramref name="parameters"/> (validated at generation time -- see the
    /// transpiler's payment-gateway call-validation pass).
    /// </summary>
    public async Task<IDictionary<string, object?>> ChargeAsync(
        IDictionary<string, object?> parameters, CancellationToken cancellationToken = default)
    {
        if (!parameters.TryGetValue("amount", out var amountObj) || amountObj is not long and not int)
        {
            return new Dictionary<string, object?> { ["success"] = false, ["error"] = "Missing required parameter: amount" };
        }
        var amount = Convert.ToInt64(amountObj);
        var currency = parameters.TryGetValue("currency", out var currencyObj) && currencyObj is string currencyStr ? currencyStr : DefaultCurrency;
        var source = parameters.TryGetValue("source", out var sourceObj) && sourceObj is string sourceStr ? sourceStr : string.Empty;
        if (TestMode)
        {
            var txId = $"test_ch_{DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}";
            return new Dictionary<string, object?> { ["success"] = true, ["transactionId"] = txId, ["amount"] = amount, ["currency"] = currency };
        }
        await EnsureApiKeyAsync().ConfigureAwait(false);
        try
        {
            var service = new Stripe.ChargeService();
            var options = new Stripe.ChargeCreateOptions
            {
                Amount = amount,
                Currency = currency,
                Source = source,
            };
            if (parameters.TryGetValue("metadata", out var metadataObj) && metadataObj is IDictionary<string, object?> metadataDict)
            {
                options.Metadata = metadataDict.ToDictionary(kv => kv.Key, kv => kv.Value?.ToString() ?? string.Empty);
            }
            var charge = await service.CreateAsync(options, cancellationToken: cancellationToken).ConfigureAwait(false);
            return new Dictionary<string, object?> { ["success"] = true, ["transactionId"] = charge.Id, ["status"] = charge.Status };
        }
        catch (Stripe.StripeException ex)
        {
            return new Dictionary<string, object?> { ["success"] = false, ["error"] = ex.Message };
        }
    }

    /// <summary>Process a refund. Reads transactionId/amount from <paramref name="parameters"/>.</summary>
    public async Task<IDictionary<string, object?>> RefundAsync(
        IDictionary<string, object?> parameters, CancellationToken cancellationToken = default)
    {
        if (!parameters.TryGetValue("transactionId", out var transactionIdObj) || transactionIdObj is not string transactionId)
        {
            return new Dictionary<string, object?> { ["success"] = false, ["error"] = "Missing required parameter: transactionId" };
        }
        if (TestMode)
        {
            return new Dictionary<string, object?> { ["success"] = true, ["refundId"] = $"test_re_{DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}" };
        }
        await EnsureApiKeyAsync().ConfigureAwait(false);
        try
        {
            var options = new Stripe.RefundCreateOptions { Charge = transactionId };
            if (parameters.TryGetValue("amount", out var amountObj) && amountObj is not null)
            {
                options.Amount = Convert.ToInt64(amountObj);
            }
            var refund = await new Stripe.RefundService().CreateAsync(options, cancellationToken: cancellationToken).ConfigureAwait(false);
            return new Dictionary<string, object?> { ["success"] = true, ["refundId"] = refund.Id, ["status"] = refund.Status };
        }
        catch (Stripe.StripeException ex)
        {
            return new Dictionary<string, object?> { ["success"] = false, ["error"] = ex.Message };
        }
    }

